import { TEAM, INDIVIDUAL } from '../../constants/participantConstants.mjs';

function getParticipation({ tournamentRecord }) {
    const tournamentId = tournamentRecord?.tournamentId;
    if (!tournamentId)
        return [];
    const shared = {
        tournamentId,
        tournamentName: tournamentRecord.tournamentName,
        startDate: tournamentRecord.startDate,
        endDate: tournamentRecord.endDate,
        eventCount: tournamentRecord.events?.length ?? 0,
        providerId: tournamentRecord.parentOrganisation?.organisationId,
    };
    const entries = [];
    const seen = new Set();
    const add = (subjectType, issued, participantId) => {
        const subjectId = subjectType === TEAM ? issued?.participantId : issued?.personId;
        if (!subjectId || !participantId)
            return;
        const key = `${subjectType}|${subjectId}|${participantId}`;
        if (seen.has(key))
            return;
        seen.add(key);
        entries.push({
            subjectType,
            subjectId,
            organisationId: issued?.organisationId,
            participantId,
            ...shared,
        });
    };
    for (const participant of tournamentRecord.participants ?? []) {
        if (participant?.participantType === TEAM) {
            for (const issued of participant.participantOtherIds ?? [])
                add('TEAM', issued, participant.participantId);
        }
        else if (participant?.participantType === INDIVIDUAL) {
            for (const issued of participant.person?.personOtherIds ?? [])
                add('PERSON', issued, participant.participantId);
        }
    }
    return entries;
}

export { getParticipation };
