import { modifyCollectionDefinition } from './modifyCollectionDefinition.mjs';
import { removeCollectionDefinition } from './removeCollectionDefinition.mjs';
import { compareTieFormats } from '../../query/hierarchical/tieFormats/compareTieFormats.mjs';
import { addCollectionDefinition } from './addCollectionDefinition.mjs';
import { copyTieFormat } from '../../query/hierarchical/tieFormats/copyTieFormat.mjs';
import { getTieFormat } from '../../query/hierarchical/tieFormats/getTieFormat.mjs';
import { decorateResult } from '../../functions/global/decorateResult.mjs';
import { validateTieFormat } from '../../validators/validateTieFormat.mjs';
import { numericSortValue } from '../../tools/arrays.mjs';
import { xa } from '../../tools/extractAttributes.mjs';
import { INVALID_TIE_FORMAT } from '../../constants/errorConditionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function modifyTieFormat({ updateInProgressMatchUps = false, tieFormatComparison, modifiedTieFormat, tournamentRecord, considerations, drawDefinition, structureId, matchUpId, eventId, uuids, event, }) {
    const stack = 'modifyTieFormat';
    if (!validateTieFormat({ tieFormat: modifiedTieFormat }).valid) {
        return decorateResult({
            result: { error: INVALID_TIE_FORMAT },
            info: 'falied validation',
            stack,
        });
    }
    const result = getTieFormat({
        drawDefinition,
        structureId,
        matchUpId,
        eventId,
        event,
    });
    if (result.error)
        return decorateResult({ result, stack });
    const { matchUp, tieFormat: existingTieFormat } = result;
    const tieFormat = copyTieFormat(existingTieFormat);
    const comparison = compareTieFormats({
        descendant: modifiedTieFormat,
        ancestor: tieFormat,
        considerations,
    });
    if (comparison.invalid) {
        return decorateResult({
            context: { invalid: comparison.invalid },
            result: { error: INVALID_TIE_FORMAT },
            stack,
        });
    }
    if (!comparison?.different) {
        return decorateResult({
            result: { ...SUCCESS },
            info: 'Nothing to do',
            stack,
        });
    }
    const existingCollectionIds = tieFormat.collectionDefinitions.map(({ collectionId }) => collectionId);
    const updatedCollectionIds = modifiedTieFormat.collectionDefinitions.map(({ collectionId }) => collectionId);
    const removedCollectionIds = existingCollectionIds.filter((collectionId) => !updatedCollectionIds.includes(collectionId));
    const addedCollectionDefinitions = modifiedTieFormat.collectionDefinitions.filter(({ collectionId }) => !existingCollectionIds.includes(collectionId));
    const addedCollectionIds = addedCollectionDefinitions.map(xa('collectionId'));
    const modifications = [];
    let processedTieFormat;
    const tieFormatName = modifiedTieFormat.tieFormatName;
    for (const collectionDefinition of modifiedTieFormat.collectionDefinitions) {
        if (addedCollectionIds.includes(collectionDefinition.collectionId))
            continue;
        const result = modifyCollectionDefinition({
            updateInProgressMatchUps,
            ...collectionDefinition,
            tournamentRecord,
            tieFormatName,
            drawDefinition,
            structureId,
            matchUpId,
            eventId,
            event,
        });
        if (result.modifications)
            modifications.push(...result.modifications);
        if (result.error)
            return decorateResult({ result, stack });
        if (result.tieFormat)
            processedTieFormat = result.tieFormat;
    }
    for (const collectionDefinition of addedCollectionDefinitions) {
        const result = addCollectionDefinition({
            updateInProgressMatchUps,
            collectionDefinition,
            tournamentRecord,
            drawDefinition,
            tieFormatName,
            structureId,
            matchUpId,
            matchUp,
            eventId,
            uuids,
            event,
        });
        if (result.error)
            return decorateResult({ result, stack });
        if (result.tieFormat)
            processedTieFormat = result.tieFormat;
    }
    for (const collectionId of removedCollectionIds) {
        const result = removeCollectionDefinition({
            updateInProgressMatchUps,
            tieFormatComparison,
            tournamentRecord,
            drawDefinition,
            tieFormatName,
            collectionId,
            structureId,
            matchUpId,
            eventId,
            matchUp,
            event,
        });
        if (result.error)
            return decorateResult({ result, stack });
        if (result.tieFormat)
            processedTieFormat = result.tieFormat;
    }
    const changedTieFormatName = existingTieFormat?.tieFormatName !== tieFormatName;
    if (changedTieFormatName) {
        processedTieFormat.tieFormatName = tieFormatName;
        modifications.push({ tieFormatName });
    }
    else if (modifications.length || addedCollectionIds.length || removedCollectionIds.length) {
        delete processedTieFormat.tieFormatName;
        modifications.push('tieFormatName removed: modifications without new tieFormatName');
    }
    processedTieFormat.collectionDefinitions = processedTieFormat.collectionDefinitions
        .sort((a, b) => numericSortValue(a.collectionOrder) - numericSortValue(b.collectionOrder))
        .map((def, i) => ({ ...def, collectionOrder: i + 1 }));
    return {
        processedTieFormat: copyTieFormat(processedTieFormat),
        modifications,
        ...SUCCESS,
    };
}

export { modifyTieFormat };
