import { getMinFinishingPositionRange } from '../../functions/sorters/structureSort.mjs';
import { isCompletedStructure } from '../../query/drawDefinition/structureActions.mjs';
import { getPlayoffStructures } from '../../query/structure/structureGetter.mjs';
import { automatedPositioning } from './automatedPositioning.mjs';
import { isAdHoc } from '../../query/drawDefinition/isAdHoc.mjs';
import { DRAW_DEFINITION_NOT_FOUND, INCOMPLETE_SOURCE_STRUCTURE } from '../../constants/errorConditionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function automatedPlayoffPositioning(params) {
    const { applyPositioning = true, provisionalPositioning, tournamentRecord, drawDefinition, seedingProfile, structureId, placeByes, seedsOnly, random, } = params;
    if (!drawDefinition)
        return { error: DRAW_DEFINITION_NOT_FOUND };
    const structureIsComplete = isCompletedStructure({
        drawDefinition,
        structureId,
    });
    if (!structureIsComplete && !provisionalPositioning) {
        return { error: INCOMPLETE_SOURCE_STRUCTURE };
    }
    const playoffStructures = getPlayoffStructures({
        drawDefinition,
        structureId,
    }).playoffStructures?.sort((a, b) => getMinFinishingPositionRange(a) - getMinFinishingPositionRange(b));
    const structurePositionAssignments = [];
    const positioningReports = [];
    if (playoffStructures) {
        for (const structure of playoffStructures) {
            if (isAdHoc({ structure }))
                continue;
            const { structureId: playoffStructureId } = structure;
            const result = automatedPositioning({
                structureId: playoffStructureId,
                provisionalPositioning,
                applyPositioning,
                tournamentRecord,
                drawDefinition,
                seedingProfile,
                placeByes,
                seedsOnly,
                random,
            });
            if (result.error)
                return result;
            if (result.positionAssignments) {
                structurePositionAssignments.push({
                    positionAssignments: result.positionAssignments,
                    structureId: playoffStructureId,
                });
            }
            if (result.positioningReport)
                positioningReports.push(result.positioningReport);
        }
    }
    return { ...SUCCESS, structurePositionAssignments, positioningReports };
}

export { automatedPlayoffPositioning };
