import { getStructureReports } from '../../structure/structureReport.mjs';
import { nowIso } from '../../../tools/clock.mjs';
import { STRUCTURE_REPORT } from '../../../constants/reportConstants.mjs';

function wrapStructureReport({ tournamentRecord, }) {
    const result = getStructureReports({ tournamentRecord });
    if (result.error)
        return result;
    const eventNameMap = {};
    const drawNameMap = {};
    const drawSizeMap = {};
    for (const event of tournamentRecord.events ?? []) {
        eventNameMap[event.eventId] = event.eventName ?? '';
        for (const draw of event.drawDefinitions ?? []) {
            drawNameMap[draw.drawId] = draw.drawName ?? '';
            const mainStructure = draw.structures?.find((s) => s.stage === 'MAIN' && s.stageSequence === 1);
            if (mainStructure?.positionAssignments) {
                drawSizeMap[draw.drawId] = mainStructure.positionAssignments.length;
            }
        }
    }
    const participantNameMap = {};
    const participantIdMap = {};
    for (const p of tournamentRecord.participants ?? []) {
        participantNameMap[p.participantId] = p.participantName ?? '';
        participantIdMap[p.participantId] = p.participantId;
        if (p.person?.personId) {
            participantNameMap[p.person.personId] = p.participantName ?? '';
            participantIdMap[p.person.personId] = p.participantId;
        }
    }
    const columns = [
        { key: 'eventName', title: 'Event', type: 'string' },
        { key: 'drawName', title: 'Draw', type: 'string' },
        { key: 'stage', title: 'Stage', type: 'string' },
        { key: 'drawType', title: 'Draw Type', type: 'string' },
        { key: 'drawSize', title: 'Draw Size', type: 'number' },
        { key: 'matchUpsCount', title: 'MatchUps', type: 'number' },
        { key: 'winner', title: 'Winner', type: 'string' },
        { key: 'seedingBasis', title: 'Seeding Basis', type: 'string' },
    ];
    const rows = (result.structureReports ?? []).map((report) => {
        const winnerName = participantNameMap[report.winningPersonId] || participantNameMap[report.winningTeamId] || '';
        const winningParticipantId = participantIdMap[report.winningPersonId] || participantIdMap[report.winningTeamId] || '';
        return {
            winningParticipantId,
            eventId: report.eventId ?? '',
            eventName: eventNameMap[report.eventId] || '',
            drawId: report.drawId ?? '',
            drawName: drawNameMap[report.drawId] || '',
            stage: report.stage ?? '',
            drawType: report.drawType ?? '',
            drawSize: drawSizeMap[report.drawId] ?? '',
            matchUpsCount: report.matchUpsCount ?? '',
            winner: winnerName,
            seedingBasis: report.seedingBasis ?? '',
        };
    });
    return {
        reportId: STRUCTURE_REPORT,
        generatedAt: nowIso(),
        columns,
        rows,
        summary: {
            eventStructureReports: result.eventStructureReports ?? [],
            flightReports: result.flightReports ?? [],
        },
    };
}

export { wrapStructureReport };
