import { deleteParticipants } from '../participants/deleteParticipants.mjs';
import { getStageEntries } from '../../query/drawDefinition/getStageEntries.mjs';
import { decorateResult } from '../../functions/global/decorateResult.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { getParticipantId } from '../../functions/global/extractors.mjs';
import { removeEventEntries } from './removeEventEntries.mjs';
import { addEventEntries } from './addEventEntries.mjs';
import { arrayIndices } from '../../tools/arrays.mjs';
import { TOURNAMENT_RECORD, PARTICIPANT_ID, EVENT } from '../../constants/attributeConstants.mjs';
import { PAIR, TEAM_PARTICIPANT } from '../../constants/participantConstants.mjs';
import { DOUBLES_EVENT, TEAM_EVENT } from '../../constants/eventConstants.mjs';
import { UNGROUPED } from '../../constants/entryStatusValues.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { INVALID_EVENT_TYPE, PARTICIPANT_NOT_FOUND, INVALID_PARTICIPANT_TYPE, PARTICIPANT_ENTRY_NOT_FOUND } from '../../constants/errorConditionConstants.mjs';

function destroyGroupEntry({ removeGroupParticipant, tournamentRecord, drawDefinition, participantId, drawId, stage, event, }) {
    const stack = 'destroyGroupEntry';
    const paramsCheck = requireParams({ tournamentRecord, participantId, event }, [
        TOURNAMENT_RECORD,
        PARTICIPANT_ID,
        EVENT,
    ]);
    if (paramsCheck.error)
        return paramsCheck;
    if (!event.eventType || ![DOUBLES_EVENT, TEAM_EVENT].includes(event.eventType)) {
        return decorateResult({ result: { error: INVALID_EVENT_TYPE }, stack });
    }
    const tournamentParticipants = tournamentRecord.participants ?? [];
    const participant = tournamentParticipants.find((participant) => participant.participantId === participantId);
    if (!participant) {
        return decorateResult({ result: { error: PARTICIPANT_NOT_FOUND }, stack });
    }
    if (!participant.participantType ||
        ![PAIR, TEAM_PARTICIPANT].includes(participant.participantType) ||
        (participant.participantType === TEAM_PARTICIPANT && event.eventType !== TEAM_EVENT) ||
        (participant.participantType === PAIR && event.eventType !== DOUBLES_EVENT)) {
        return { error: INVALID_PARTICIPANT_TYPE };
    }
    const eventEntries = event.entries ?? [];
    const entry = eventEntries.find((entry) => entry.participantId === participantId);
    if (!entry)
        return { error: PARTICIPANT_ENTRY_NOT_FOUND };
    const { stageEntries } = getStageEntries({
        selected: false,
        drawDefinition,
        drawId,
        event,
        stage,
    });
    const groupedParticipantIds = stageEntries.map(getParticipantId);
    const individualParticipantIdsInGroups = tournamentParticipants
        .filter(({ participantId }) => groupedParticipantIds.includes(participantId))
        .map(({ individualParticipantIds }) => individualParticipantIds)
        .flat()
        .filter(Boolean);
    const individualParticipantIds = participant.individualParticipantIds?.filter((participantId) => arrayIndices(participantId, individualParticipantIdsInGroups).length === 1);
    let result = removeEventEntries({
        participantIds: [participantId],
        event,
    });
    if (result.error)
        return result;
    if (individualParticipantIds?.length) {
        result = addEventEntries({
            participantIds: individualParticipantIds,
            entryStatus: UNGROUPED,
            entryStage: entry.entryStage,
            tournamentRecord,
            drawDefinition,
            drawId,
            event,
        });
        if (result.error)
            return result;
    }
    let participantRemoved;
    if (removeGroupParticipant) {
        const result = deleteParticipants({
            participantIds: [participantId],
            tournamentRecord,
        });
        if (result.success)
            participantRemoved = true;
    }
    return { ...SUCCESS, participantRemoved };
}

export { destroyGroupEntry };
