import { modifyParticipantsNotice } from '../notifications/participantNotifications.mjs';
import { findTournamentParticipant } from '../../acquire/findTournamentParticipant.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { getTopics } from '../../global/state/globalState.mjs';
import { nowIso } from '../../tools/clock.mjs';
import { MISSING_VALUE, PARTICIPANT_NOT_FOUND, INVALID_VALUES } from '../../constants/errorConditionConstants.mjs';
import { TOURNAMENT_RECORD, PARTICIPANT_ID } from '../../constants/attributeConstants.mjs';
import { MODIFY_PARTICIPANTS } from '../../constants/topicConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function addPersonOtherId({ tournamentRecord, participantId, organisationId, personId, occurredAt, }) {
    const paramsCheck = requireParams({ tournamentRecord, participantId }, [TOURNAMENT_RECORD, PARTICIPANT_ID]);
    if (paramsCheck.error)
        return paramsCheck;
    if (!organisationId)
        return { error: MISSING_VALUE, info: 'Missing organisationId' };
    if (!personId)
        return { error: MISSING_VALUE, info: 'Missing personId' };
    const { participant } = findTournamentParticipant({
        tournamentRecord,
        participantId,
    });
    if (!participant)
        return { error: PARTICIPANT_NOT_FOUND };
    if (!participant.person)
        return {
            error: INVALID_VALUES,
            info: 'Participant has no person — only INDIVIDUAL participants accept personOtherIds',
        };
    const person = participant.person;
    person.personOtherIds ??= [];
    const existing = person.personOtherIds.find((entry) => entry?.organisationId === organisationId);
    if (existing) {
        if (existing.personId === personId) {
            return { ...SUCCESS };
        }
        existing.personId = personId;
        existing.updatedAt = occurredAt ?? nowIso();
    }
    else {
        person.personOtherIds.push({
            organisationId,
            personId,
            createdAt: occurredAt ?? nowIso(),
        });
    }
    const { topics } = getTopics();
    if (topics.includes(MODIFY_PARTICIPANTS)) {
        modifyParticipantsNotice({
            tournamentId: tournamentRecord.tournamentId,
            participants: [participant],
        });
    }
    return { ...SUCCESS };
}

export { addPersonOtherId };
